"testimonials":{"title":"Loved by the Community","subtitle":"What early users are saying about MoliTutu.","quote1":"Finally, an image tool that respects my privacy. The local API proxy is a game-changer for my automation workflow.","author1":"Sarah Chen","role1":"Full-stack Developer","quote2":"I compress hundreds of product images weekly. MoliTutu cut my workflow time in half. The R2 integration is seamless.","author2":"Marcus Rivera","role2":"E-commerce Manager","quote3":"Open source, local-first, and beautifully simple. This is how desktop tools should be built. Excited to contribute!","author3":"Kenji Tanaka","role3":"Open Source Contributor"},
"pricing":{"title":"Simple Pricing","subtitle":"MoliTutu itself is free. Forever. You only pay for the cloud storage you use.","free":{"title":"MoliTutu","priceDesc":"Free forever. Open source.","f1":"Unlimited image compression","f2":"All formats: JPG, PNG, WebP, AVIF, GIF","f3":"Local API proxy for automation","f4":"Batch processing (unlimited)","f5":"MIT open source license"},"download":"Download Free","r2":{"title":"Cloudflare R2","priceDesc":"Pay-as-you-go cloud storage","f1":"10 GB storage — free","f2":"1M reads/month — free","f3":"No egress fees","f4":"Global CDN via Cloudflare","f5":"S3-compatible API","cta":"Learn About R2"}},
