"features":{"title":"Todo lo que Necesitas","subtitle":"Desde compresión inteligente hasta subida a la nube con un clic — MoliTutu maneja todo el flujo de trabajo.","compression":{"title":"Compresión Inteligente","desc":"Algoritmos inteligentes reducen el tamaño hasta un 80% sin pérdida perceptible de calidad. Modos lossy y lossless."},"upload":{"title":"Subida a R2","desc":"Integración perfecta con Cloudflare R2. Configura una vez, sube al instante. Generación automática de URL pública."},"privacy":{"title":"Privacidad Primero","desc":"Todo el procesamiento se ejecuta localmente. Tus imágenes van directamente a tu bucket R2. Nunca vemos tus datos."},"proxy":{"title":"Proxy API Local","desc":"Servidor HTTP integrado para subidas programáticas. Integra MoliTutu en tus scripts, CI/CD o flujos personalizados."}},
"how":{"title":"Cómo Funciona","subtitle":"Tres pasos simples de la imagen a la URL publicada.","step1":{"title":"Configurar R2","desc":"Ingresa tus credenciales de Cloudflare R2 en la configuración. Una vez configurado, uso permanente. Soporta múltiples buckets."},"step2":{"title":"Arrastrar y Soltar","desc":"Arrastra tus imágenes a la app. La compresión y optimización comienzan automáticamente. Procesa cientos a la vez."},"step3":{"title":"Obtener Enlace","desc":"Copia la URL pública con un clic. Listo para incrustar en blogs, apps o compartir con tu equipo."}},
"why":{"title":"¿Por Qué MoliTutu?","subtitle":"Construido de forma diferente. Sin suscripciones. Sin dependencia en la nube. Una herramienta que respeta tu privacidad y productividad.","pillar1":{"title":"Rápido como un Rayo","desc":"Procesa ~50 imágenes por segundo con tuberías de compresión paralelas. Sin esperas, sin colas."},"pillar2":{"title":"Calidad sin Pérdidas","desc":"Los algoritmos inteligentes preservan la fidelidad visual mientras reducen drásticamente el tamaño."},"pillar3":{"title":"100% Privado","desc":"Todo se ejecuta localmente. Ningún dato toca nuestros servidores. Tus imágenes son tuyas."},"pillar4":{"title":"Sin Configuración","desc":"Descarga, inicia y ya. Configuración mínima con valores predeterminados inteligentes que funcionan."}},
"useCases":{"title":"Para Quién Es","subtitle":"MoliTutu se adapta a cualquier flujo de trabajo con imágenes y web.","blogger":{"title":"Blogueros y Creadores","desc":"Optimiza imágenes destacadas y capturas para páginas más rápidas. URLs con CDN para tu CMS."},"developer":{"title":"Desarrolladores","desc":"Integra mediante proxy API local en pipelines de build, CI/CD o scripts de automatización."},"designer":{"title":"Diseñadores","desc":"Comprime portafolios y maquetas antes de compartir. Mantén la calidad visual con 60-80% menos tamaño."},"devops":{"title":"DevOps y Plataforma","desc":"Optimiza por lotes imágenes de productos y subidas de usuarios. Integra en tu pipeline multimedia."}},
"tech":{"title":"Detalles Técnicos","subtitle":"Construido con Tauri y Rust para máximo rendimiento y mínimo consumo.","formatsTitle":"Formatos Soportados","formatJPEG":"Lossy + Progresivo","formatPNG":"Lossless + Opt. Paleta","formatWebP":"Lossy + Lossless","formatAVIF":"Alta Eficiencia","formatGIF":"Optimización de Fotogramas","benchmarksTitle":"Benchmarks","benchRatio":"Ratio de Compresión","benchSpeed":"Velocidad de Procesamiento","benchMemory":"Memoria (inactivo)","benchMemoryLoad":"Memoria (carga)","benchAPI":"Latencia API","stackTitle":"Stack Tecnológico","apiExample":"Ejemplo API — Subida con cURL"},
"testimonials":{"title":"Querido por la Comunidad","subtitle":"Lo que dicen los primeros usuarios sobre MoliTutu.","quote1":"Por fin una herramienta de imágenes que respeta mi privacidad. El proxy API local es un cambio radical para mi automatización.","author1":"Sara García","role1":"Desarrolladora Full-stack","quote2":"Comprimo cientos de imágenes de producto cada semana. MoliTutu redujo mi tiempo a la mitad. La integración con R2 es perfecta.","author2":"Marco Rivera","role2":"Gerente de E-commerce","quote3":"Open source, local-first y bellamente simple. Así deberían construirse las herramientas de escritorio. ¡Emocionado de contribuir!","author3":"Kenji Tanaka","role3":"Contribuidor Open Source"},
