"hero":{"badge":"오픈소스 · v0.4.0","titleLine1":"스마트 이미지","titleLine2":"압축","titleLine3":"클라우드 업로드","desc":"무료 오픈소스 데스크탑 앱으로 이미지를 지능적으로 압축하고 Cloudflare R2에 직접 업로드하세요. 프라이버시 우선, 로컬 전용.","download":"지금 다운로드","github":"GitHub에서 보기","exampleBefore":"압축 전","exampleAfter":"압축 후","exampleFormats":"JPG · PNG · WebP · AVIF","exampleUpload":"→ R2 업로드 준비"},
"features":{"title":"필요한 모든 것","subtitle":"스마트 압축부터 원클릭 클라우드 업로드까지 — MoliTutu가 전체 워크플로를 처리합니다.","compression":{"title":"스마트 압축","desc":"지능형 알고리즘이 화질 저하 없이 파일 크기를 최대 80%까지 줄입니다. 손실 및 무손실 모드 지원."},"upload":{"title":"R2 업로드","desc":"Cloudflare R2와 완벽한 통합. 한 번 설정하면 즉시 업로드 가능. 자동 공개 URL 생성."},"privacy":{"title":"프라이버시 우선","desc":"모든 처리는 로컬에서 실행됩니다. 이미지는 직접 R2 버킷으로 업로드됩니다. 데이터가 외부로 유출되지 않습니다."},"proxy":{"title":"로컬 API 프록시","desc":"프로그래매틱 업로드를 위한 내장 HTTP 서버. 스크립트, CI/CD, 사용자 정의 워크플로에 통합 가능."}},
"how":{"title":"사용 방법","subtitle":"이미지에서 공개 URL까지 세 가지 간단한 단계.","step1":{"title":"R2 설정","desc":"설정에서 Cloudflare R2 자격 증명을 입력하세요. 한 번 설정으로 영구 사용. 여러 버킷 프로필 지원."},"step2":{"title":"드래그 & 드롭","desc":"이미지를 앱으로 드래그하세요. 압축과 최적화가 자동으로 시작됩니다. 한 번에 수백 장 처리."},"step3":{"title":"링크 획득","desc":"원클릭으로 공개 URL을 복사하세요. 블로그, 앱에 삽입하거나 팀과 공유할 준비 완료."}},
"why":{"title":"왜 MoliTutu인가요?","subtitle":"다르게 만들었습니다. 구독제 없음. 클라우드 의존성 없음. 프라이버시와 생산성을 존중하는 도구.","pillar1":{"title":"초고속 처리","desc":"병렬 압축 파이프라인으로 초당 약 50장의 이미지 처리. 대기 시간 없음, 큐 없음."},"pillar2":{"title":"무손실 품질","desc":"지능형 알고리즘이 파일 크기를 획기적으로 줄이면서도 화질을 완벽하게 보존합니다."},"pillar3":{"title":"100% 프라이빗","desc":"모든 작업이 로컬에서 실행됩니다. 어떤 데이터도 서버에 전송되지 않습니다. 이미지는 항상 내 것입니다."},"pillar4":{"title":"제로 설정","desc":"다운로드하고 실행하기만 하면 됩니다. 최소한의 설정으로 바로 사용 가능한 스마트한 기본값."}},
"useCases":{"title":"추천 사용자","subtitle":"MoliTutu는 이미지와 웹 관련 모든 워크플로에 적합합니다.","blogger":{"title":"블로거 & 크리에이터","desc":"페이지 로딩 속도 향상을 위해 대표 이미지와 스크린샷을 최적화하세요. CMS용 CDN URL 제공."},"developer":{"title":"개발자","desc":"로컬 API 프록시를 통해 빌드 파이프라인, CI/CD, 자동화 스크립트에 통합하세요."},"designer":{"title":"디자이너","desc":"공유 전에 포트폴리오와 목업을 압축하세요. 60-80% 더 작은 크기로 화질 유지."},"devops":{"title":"DevOps & 플랫폼","desc":"제품 이미지와 사용자 업로드를 일괄 최적화하세요. 미디어 파이프라인에 통합."}},
