"features":{"title":"Tudo que Você Precisa","subtitle":"Da compressão inteligente ao upload cloud com um clique — MoliTutu cuida de todo o fluxo de trabalho.","compression":{"title":"Compressão Inteligente","desc":"Algoritmos inteligentes reduzem o tamanho em até 80% sem perda perceptível de qualidade. Modos lossy e lossless."},"upload":{"title":"Upload R2","desc":"Integração perfeita com Cloudflare R2. Configure uma vez, envie instantaneamente. Geração automática de URL pública."},"privacy":{"title":"Privacidade Primeiro","desc":"Todo processamento é local. Suas imagens vão direto para seu bucket R2. Nunca vemos seus dados."},"proxy":{"title":"Proxy API Local","desc":"Servidor HTTP integrado para uploads programáticos. Integre MoliTutu em scripts, CI/CD ou fluxos personalizados."}},
"how":{"title":"Como Funciona","subtitle":"Três passos simples da imagem à URL publicada.","step1":{"title":"Configurar R2","desc":"Insira suas credenciais Cloudflare R2 nas configurações. Configuração única, uso permanente. Vários perfis de bucket."},"step2":{"title":"Arraste e Solte","desc":"Arraste suas imagens para o app. Compressão e otimização começam automaticamente. Processe centenas de uma vez."},"step3":{"title":"Obter Link","desc":"Copie a URL pública com um clique. Pronto para incorporar em blogs, apps ou compartilhar com sua equipe."}},
"why":{"title":"Por que MoliTutu?","subtitle":"Construído de forma diferente. Sem assinaturas. Sem dependência de nuvem. Uma ferramenta que respeita sua privacidade e produtividade.","pillar1":{"title":"Super Rápido","desc":"Processa ~50 imagens por segundo com pipelines paralelos. Sem espera, sem filas."},"pillar2":{"title":"Qualidade sem Perdas","desc":"Algoritmos inteligentes preservam a fidelidade visual enquanto reduzem drasticamente o tamanho."},"pillar3":{"title":"100% Privado","desc":"Tudo executa localmente. Nenhum dado toca nossos servidores. Suas imagens são suas."},"pillar4":{"title":"Configuração Zero","desc":"Baixe, inicie e use. Configuração mínima com padrões inteligentes que funcionam."}},
"useCases":{"title":"Para Quem é","subtitle":"MoliTutu se adapta a qualquer fluxo de trabalho com imagens e web.","blogger":{"title":"Blogueiros & Criadores","desc":"Otimize imagens destacadas e capturas para páginas mais rápidas. URLs com CDN para seu CMS."},"developer":{"title":"Desenvolvedores","desc":"Integre via proxy API local em pipelines de build, CI/CD ou scripts de automação."},"designer":{"title":"Designers","desc":"Comprima portfólios e mockups antes de compartilhar. Mantenha a qualidade com 60-80% menos tamanho."},"devops":{"title":"DevOps & Plataforma","desc":"Otimize em lote imagens de produtos e uploads de usuários. Integre em seu pipeline de mídia."}},
