"features":{"title":"वह सब जो आपको चाहिए","subtitle":"स्मार्ट कंप्रेशन से लेकर वन-क्लिक क्लाउड अपलोड तक — MoliTutu पूरे वर्कफ़्लो को संभालता है।","compression":{"title":"स्मार्ट कंप्रेशन","desc":"बुद्धिमान एल्गोरिदम गुणवत्ता खोए बिना फ़ाइल आकार को 80% तक कम करते हैं। लॉसी और लॉसलेस मोड।"},"upload":{"title":"R2 अपलोड","desc":"Cloudflare R2 के साथ सहज एकीकरण। एक बार कॉन्फ़िगर करें, तुरंत अपलोड करें। स्वचालित सार्वजनिक URL जनरेशन।"},"privacy":{"title":"गोपनीयता पहले","desc":"सभी प्रसंस्करण स्थानीय रूप से होता है। आपकी छवियां सीधे आपके R2 बकेट में जाती हैं। हम आपका डेटा कभी नहीं देखते।"},"proxy":{"title":"स्थानीय API प्रॉक्सी","desc":"प्रोग्रामेटिक अपलोड के लिए अंतर्निहित HTTP सर्वर। MoliTutu को अपनी स्क्रिप्ट, CI/CD या कस्टम वर्कफ़्लो में एकीकृत करें।"}},
"how":{"title":"यह कैसे काम करता है","subtitle":"इमेज से प्रकाशित URL तक तीन सरल चरण।","step1":{"title":"R2 कॉन्फ़िगर करें","desc":"सेटिंग्स में अपनी Cloudflare R2 क्रेडेंशियल दर्ज करें। एक बार सेटअप, स्थायी उपयोग। कई बकेट प्रोफ़ाइल सपोर्ट।"},"step2":{"title":"ड्रैग और ड्रॉप","desc":"अपनी छवियों को ऐप में खींचें। कंप्रेशन और ऑप्टिमाइज़ेशन स्वचालित रूप से शुरू होता है। एक साथ सैकड़ों प्रक्रिया करें।"},"step3":{"title":"लिंक प्राप्त करें","desc":"एक क्लिक में सार्वजनिक URL कॉपी करें। ब्लॉग, ऐप में एम्बेड करने या टीम के साथ साझा करने के लिए तैयार।"}},
"why":{"title":"MoliTutu क्यों?","subtitle":"अलग तरीके से बनाया गया। कोई सब्सक्रिप्शन नहीं। कोई क्लाउड निर्भरता नहीं। एक टूल जो आपकी गोपनीयता और उत्पादकता का सम्मान करता है।","pillar1":{"title":"बिजली की तेज़ी","desc":"समानांतर कंप्रेशन पाइपलाइनों के साथ प्रति सेकंड ~50 इमेज प्रोसेस करता है। बिना प्रतीक्षा के।"},"pillar2":{"title":"दोषरहित गुणवत्ता","desc":"बुद्धिमान एल्गोरिदम फ़ाइल आकार को नाटकीय रूप से कम करते हुए दृश्य निष्ठा को संरक्षित करते हैं।"},"pillar3":{"title":"100% निजी","desc":"सब कुछ स्थानीय रूप से चलता है। कोई डेटा हमारे सर्वर को स्पर्श नहीं करता। आपकी छवियां आपकी हैं।"},"pillar4":{"title":"शून्य कॉन्फ़िगरेशन","desc":"डाउनलोड करें, लॉन्च करें और शुरू करें। न्यूनतम सेटअप जो काम करता है।"}},
"useCases":{"title":"यह किसके लिए है","subtitle":"MoliTutu किसी भी वर्कफ़्लो में फ़िट बैठता है जिसमें इमेज और वेब शामिल हैं।","blogger":{"title":"ब्लॉगर और क्रिएटर","desc":"तेज़ पेज लोड के लिए फ़ीचर्ड इमेज और स्क्रीनशॉट ऑप्टिमाइज़ करें। अपने CMS के लिए CDN URL।"},"developer":{"title":"डेवलपर्स","desc":"स्थानीय API प्रॉक्सी के माध्यम से बिल्ड पाइपलाइन, CI/CD या ऑटोमेशन स्क्रिप्ट में एकीकृत करें।"},"designer":{"title":"डिज़ाइनर","desc":"साझा करने से पहले पोर्टफ़ोलियो और मॉकअप को कंप्रेस करें। 60-80% छोटे आकार में दृश्य निष्ठा बनाए रखें।"},"devops":{"title":"DevOps और प्लेटफ़ॉर्म","desc":"उत्पाद इमेज और उपयोगकर्ता अपलोड को बैच में ऑप्टिमाइज़ करें। अपनी मीडिया पाइपलाइन में एकीकृत करें।"}},
