"testimonials":{"title":"समुदाय द्वारा पसंद किया गया","subtitle":"MoliTutu के बारे में शुरुआती उपयोगकर्ता क्या कह रहे हैं।","quote1":"आखिरकार एक इमेज टूल जो मेरी गोपनीयता का सम्मान करता है। स्थानीय API प्रॉक्सी मेरे ऑटोमेशन वर्कफ़्लो के लिए गेम-चेंजर है।","author1":"प्रिया शर्मा","role1":"फुल-स्टैक डेवलपर","quote2":"मैं साप्ताहिक रूप से सैकड़ों उत्पाद इमेज कंप्रेस करता हूं। MoliTutu ने मेरा कार्य समय आधा कर दिया। R2 एकीकरण सहज है।","author2":"राजेश कुमार","role2":"ई-कॉमर्स मैनेजर","quote3":"ओपन सोर्स, स्थानीय-प्रथम और खूबसूरती से सरल। इस तरह डेस्कटॉप टूल्स बनाए जाने चाहिए।","author3":"केंजी तनाका","role3":"ओपन सोर्स योगदानकर्ता"},
"pricing":{"title":"सरल मूल्य निर्धारण","subtitle":"MoliTutu स्वयं मुफ़्त है। हमेशा के लिए। आप केवल उपयोग किए गए क्लाउड स्टोरेज के लिए भुगतान करते हैं।","free":{"title":"MoliTutu","priceDesc":"हमेशा मुफ़्त · ओपन सोर्स","f1":"असीमित इमेज कंप्रेशन","f2":"सभी फॉर्मेट: JPG, PNG, WebP, AVIF, GIF","f3":"ऑटोमेशन के लिए स्थानीय API प्रॉक्सी","f4":"बैच प्रोसेसिंग (असीमित)","f5":"MIT ओपन सोर्स लाइसेंस"},"download":"मुफ्त डाउनलोड","r2":{"title":"Cloudflare R2","priceDesc":"पे-एज़-यू-गो क्लाउड स्टोरेज","f1":"10 GB स्टोरेज — मुफ़्त","f2":"1M रीड/माह — मुफ़्त","f3":"कोई एग्रेस फीस नहीं","f4":"Cloudflare के माध्यम से ग्लोबल CDN","f5":"S3-संगत API","cta":"R2 के बारे में जानें"}},
